import re

from ta_moler.cmd.hub.rfswcli.generichub import GenericHub
from moler.exceptions import CommandFailure
from moler.exceptions import ParsingDone


class AntVersion(GenericHub):
    """AntVersion command class."""

    def __init__(self, connection, port, prompt=None, newline_chars=None, runner=None):
        """
        Display ASiR pRRH image version.

        :param connection: moler connection to device, terminal when command is executed
        :param port: antenna port.
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(AntVersion, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                         runner=runner)

        self.port = port
        self.current_ret["Version"] = None
        self.current_ret["Subversion"] = None

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        return f"ant_version {self.port}"

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._command_error(line)
                self._parse_subversion(line)
                self._parse_version(line)
            except ParsingDone:
                pass
        return super(AntVersion, self).on_new_line(line, is_full_line)

    # No pRRH connected!
    _re_error = re.compile(r'(?P<ERROR>No\s+pRRH\s+connected)', re.I)

    def _command_error(self, line):
        if self._regex_helper.search_compiled(AntVersion._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("ERROR")))
            raise ParsingDone

    # subVersion = 0x80000001
    _re_subversion = re.compile(r'subVersion\s+=\s+(?P<SUBVERSION>\S+)', re.I)

    def _parse_subversion(self, line):
        if self._regex_helper.search_compiled(AntVersion._re_subversion, line):
            self.current_ret["Subversion"] = self._regex_helper.group("SUBVERSION")
            raise ParsingDone

    # Version = 0xa5140090
    _re_version = re.compile(r'Version\s+=\s+(?P<VERSION>\S+)', re.I)

    def _parse_version(self, line):
        if self._regex_helper.search_compiled(AntVersion._re_version, line):
            self.current_ret["Version"] = self._regex_helper.group("VERSION")
            raise ParsingDone


COMMAND_OUTPUT = """rfsw> ant_version 0
Version = 0xa5140090
subVersion = 0x80000001
rfsw>"""


COMMAND_KWARGS = {
    'port': 0
}


COMMAND_RESULT = {
    'Version': '0xa5140090',
    'Subversion': '0x80000001'
}
